int main(void) {
    const char *src = "hello";
    char *dst = malloc(strlen(src) + 1);  // +1 for the NUL
    if (!dst) return 1;                    // malloc can fail
    strcpy(dst, src);                      // safe: dst is big enough
    printf("%s\n", dst);
    free(dst);                             // exactly one free
    dst = NULL;                            // no dangling pointer
    return 0;
}

